#pragma GCC optimize("O3,unroll-loops,omit-frame-pointer,inline-functions")
#pragma GCC target("avx2,bmi,bmi2,lzcnt,popcnt")

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_N 26
#define MAX_CELLS (MAX_N * MAX_N)

typedef struct {
    unsigned char row, col, reg;
} Cell;

static int n, solution_count;
static Cell cells[MAX_CELLS];
static unsigned char board[MAX_N][MAX_N];
static int cat_col[MAX_N], solution[MAX_N];
static uint32_t row_used, col_used, reg_used;
static uint32_t full_mask;
static int cell_count;

static inline int possible(const Cell *p)
{
    const uint32_t rb = UINT32_C(1) << p->row;
    const uint32_t cb = UINT32_C(1) << p->col;
    const uint32_t gb = UINT32_C(1) << p->reg;

    if ((row_used & rb) ||
        (col_used & cb) ||
        (reg_used & gb))
        return 0;

    if (p->row &&
        cat_col[p->row - 1] >= 0 &&
        abs((int)p->col - cat_col[p->row - 1]) <= 1)
        return 0;

    if (p->row + 1 < n &&
        cat_col[p->row + 1] >= 0 &&
        abs((int)p->col - cat_col[p->row + 1]) <= 1)
        return 0;

    return 1;
}

static void search(int placed)
{
    if (solution_count >= 2)
        return;

    if (placed == n) {
        if (solution_count++ == 0) {
            memcpy(solution, cat_col,
                   (size_t)n * sizeof(solution[0]));
        }
        return;
    }

    unsigned short rows[MAX_N] = {0};
    unsigned short cols[MAX_N] = {0};
    unsigned short regs[MAX_N] = {0};

    for (int i = 0; i < cell_count; ++i) {
        const Cell *p = &cells[i];

        if (possible(p)) {
            ++rows[p->row];
            ++cols[p->col];
            ++regs[p->reg];
        }
    }

    int kind = -1;
    int index = -1;
    int best = MAX_CELLS + 1;

    for (int k = 0; k < n; ++k) {
        if (!(row_used & (UINT32_C(1) << k)) &&
            rows[k] < best) {
            best = rows[k];
            kind = 0;
            index = k;
        }

        if (!(col_used & (UINT32_C(1) << k)) &&
            cols[k] < best) {
            best = cols[k];
            kind = 1;
            index = k;
        }

        if (!(reg_used & (UINT32_C(1) << k)) &&
            regs[k] < best) {
            best = regs[k];
            kind = 2;
            index = k;
        }
    }

    if (best == 0 || kind == -1)
        return;

    for (int i = 0; i < cell_count; ++i) {
        const Cell *p = &cells[i];

        if ((kind == 0 && p->row != index) ||
            (kind == 1 && p->col != index) ||
            (kind == 2 && p->reg != index) ||
            !possible(p))
            continue;

        const uint32_t rb = UINT32_C(1) << p->row;
        const uint32_t cb = UINT32_C(1) << p->col;
        const uint32_t gb = UINT32_C(1) << p->reg;

        row_used |= rb;
        col_used |= cb;
        reg_used |= gb;

        cat_col[p->row] = p->col;

        search(placed + 1);

        cat_col[p->row] = -1;

        row_used &= ~rb;
        col_used &= ~cb;
        reg_used &= ~gb;

        if (solution_count >= 2)
            return;
    }
}

int main(void)
{
    if (scanf("%d", &n) != 1 ||
        n < 4 || n > MAX_N) {
        fprintf(stderr,
                "Error: grid size must be 4..26.\n");
        return EXIT_FAILURE;
    }

    full_mask = (UINT32_C(1) << n) - 1;

    uint32_t seen = 0;

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            char token[32];

            if (scanf("%31s", token) != 1 ||
                token[0] < 'A' ||
                token[0] >= 'A' + n ||
                token[1] != '\0') {
                fprintf(stderr,
                    "Error: invalid cell "
                    "at row %d, column %d.\n",
                    r + 1, c + 1);
                return EXIT_FAILURE;
            }

            int reg = token[0] - 'A';

            board[r][c] = (unsigned char)reg;

            cells[cell_count++] = (Cell){
                (unsigned char)r,
                (unsigned char)c,
                (unsigned char)reg
            };

            seen |= UINT32_C(1) << reg;
        }
    }

    if (seen != full_mask) {
        fprintf(stderr,
            "Error: expected all %d region "
            "letters A through %c.\n",
            n, 'A' + n - 1);
        return EXIT_FAILURE;
    }

    for (int r = 0; r < n; ++r)
        cat_col[r] = -1;

    search(0);

    if (solution_count == 0) {
        fprintf(stderr,
                "Error: no solution.\n");
        return EXIT_FAILURE;
    }

    if (solution_count > 1) {
        fprintf(stderr,
                "Error: multiple solutions.\n");
        return EXIT_FAILURE;
    }

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            putchar(
                (solution[r] == c ? 'a' : 'A')
                + board[r][c]
            );

            putchar(c + 1 == n ? '\n' : ' ');
        }
    }

    return EXIT_SUCCESS;
}
